import{_ as e,o as t,c as r,a2 as l}from"./chunks/framework.BXzK3EA4.js";const b=JSON.parse('{"title":"저장과 결정성 규칙","description":"","frontmatter":{},"headers":[],"relativePath":"rules/Rules-SaveDeterminism.md","filePath":"rules/Rules-SaveDeterminism.md"}'),i={name:"rules/Rules-SaveDeterminism.md"};function d(h,a,o,s,n,c){return t(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="저장과-결정성-규칙" tabindex="-1">저장과 결정성 규칙 <a class="header-anchor" href="#저장과-결정성-규칙" aria-label="Permalink to &quot;저장과 결정성 규칙&quot;">​</a></h1><blockquote><p>출처: docs/game-logic/Save-and-Determinism.md — 계약 수치는 구현 상수를 우선한다.</p></blockquote><h2 id="개요" tabindex="-1">개요 <a class="header-anchor" href="#개요" aria-label="Permalink to &quot;개요&quot;">​</a></h2><p>같은 시작값과 선택 기록은 같은 세계와 같은 사건 검사값을 강제한다. 난수는 전투·조우·세계 사건으로 가른다. 저장은 원장과 전투 중간 지점을 담되 검사값 확인 뒤에만 원본과 바꾼다.</p><h2 id="핵심-수치" tabindex="-1">핵심 수치 <a class="header-anchor" href="#핵심-수치" aria-label="Permalink to &quot;핵심 수치&quot;">​</a></h2><table tabindex="0"><thead><tr><th>항목</th><th>값</th><th>비고</th></tr></thead><tbody><tr><td>재현 입력</td><td>시작값과 선택 기록</td><td>세계 상태와 사건 기록의 검사값이 같아야 함</td></tr><tr><td>난수 스트림</td><td>전투, 조우, 세계 사건</td><td>쓰임새별 분리</td></tr><tr><td>성명 난수</td><td>인물 스트림만</td><td>다른 스트림을 쓰지 않음</td></tr><tr><td>원장 기록</td><td>원인 ID와 명령, 세계 시간, 변경 주체와 대상, 변경 전후 요약 해시, 규칙과 콘텐츠 버전</td><td>모든 상태 변경</td></tr><tr><td>인물 행위</td><td>면담·거래·후계 지지</td><td>미시 줄. 합이 임계를 넘을 때 세계 사건</td></tr><tr><td>저장 내용</td><td>판본이 붙은 세계 상태, 명령·사건의 위치, 콘텐츠 판본, 진행 중인 전투의 중간 지점</td><td></td></tr><tr><td>원자 쓰기</td><td>임시 파일에 쓴 뒤 검사값 확인, 원본과 교체</td><td></td></tr><tr><td>거부 조건</td><td>지원하지 않는 버전, 잘린 파일, 잘못된 체크섬</td><td>명확한 오류. 이전 백업 보존</td></tr><tr><td>전투 저장 시점</td><td>전투 컨텍스트 발행 전, 전투 턴이 끝난 중간 지점, 결과 정산 완료 뒤</td><td></td></tr><tr><td>중간 저장 읽기</td><td>저장된 불변 컨텍스트와 전투 명령 기록</td><td>캠페인을 다시 조회하지 않음</td></tr></tbody></table><h2 id="조항" tabindex="-1">조항 <a class="header-anchor" href="#조항" aria-label="Permalink to &quot;조항&quot;">​</a></h2><h3 id="rsave-01-재현-계약" tabindex="-1">RSAVE-01 재현 계약 <a class="header-anchor" href="#rsave-01-재현-계약" aria-label="Permalink to &quot;RSAVE-01 재현 계약&quot;">​</a></h3><p>같은 시작값과 선택 기록으로 다시 돌리면 같은 세계 상태가 나온다. 사건 기록의 검사값도 같아야 한다.</p><h3 id="rsave-02-난수-스트림" tabindex="-1">RSAVE-02 난수 스트림 <a class="header-anchor" href="#rsave-02-난수-스트림" aria-label="Permalink to &quot;RSAVE-02 난수 스트림&quot;">​</a></h3><p>무작위 값은 전투, 조우, 세계 사건처럼 쓰임새별로 나눈다. 한 스트림이 다른 스트림의 결과를 대신하지 못한다.</p><h3 id="rsave-03-교차-오염" tabindex="-1">RSAVE-03 교차 오염 <a class="header-anchor" href="#rsave-03-교차-오염" aria-label="Permalink to &quot;RSAVE-03 교차 오염&quot;">​</a></h3><p>한 시스템의 처리 순서가 다른 시스템의 결과를 흔들지 못하게 한다. 순서 의존으로 난수를 공유하지 않는다.</p><h3 id="rsave-04-원장-의무" tabindex="-1">RSAVE-04 원장 의무 <a class="header-anchor" href="#rsave-04-원장-의무" aria-label="Permalink to &quot;RSAVE-04 원장 의무&quot;">​</a></h3><p>모든 상태 변경은 사건 원장에 기록한다. 원장 없는 변경은 인정하지 않는다.</p><h3 id="rsave-05-원장-항목" tabindex="-1">RSAVE-05 원장 항목 <a class="header-anchor" href="#rsave-05-원장-항목" aria-label="Permalink to &quot;RSAVE-05 원장 항목&quot;">​</a></h3><p>원장은 원인 ID와 명령을 적는다. 세계 시간과 변경 주체와 대상이 빠지면 무효다. 변경 전후 요약 해시와 규칙·콘텐츠 버전을 함께 붙인다.</p><h3 id="rsave-06-원인-설명" tabindex="-1">RSAVE-06 원인 설명 <a class="header-anchor" href="#rsave-06-원인-설명" aria-label="Permalink to &quot;RSAVE-06 원인 설명&quot;">​</a></h3><p>원장으로 노선 봉쇄의 원인을 설명한다. 물가가 오른 까닭도 원장에서 읽는다. 인물이 세력을 떠난 이유를 원장 밖 추측으로 메우지 않는다.</p><h3 id="rsave-07-인물-미시-줄" tabindex="-1">RSAVE-07 인물 미시 줄 <a class="header-anchor" href="#rsave-07-인물-미시-줄" aria-label="Permalink to &quot;RSAVE-07 인물 미시 줄&quot;">​</a></h3><p>면담·거래·후계 지지는 인물 미시 줄로만 남긴다. 그 줄을 세계 사건으로 바로 올리지 않는다.</p><h3 id="rsave-08-임계-승격" tabindex="-1">RSAVE-08 임계 승격 <a class="header-anchor" href="#rsave-08-임계-승격" aria-label="Permalink to &quot;RSAVE-08 임계 승격&quot;">​</a></h3><p>미시 줄의 합이 임계를 넘을 때 세계 사건이 된다. 임계 미만을 세계 사건으로 승격하지 않는다.</p><h3 id="rsave-09-성명-난수" tabindex="-1">RSAVE-09 성명 난수 <a class="header-anchor" href="#rsave-09-성명-난수" aria-label="Permalink to &quot;RSAVE-09 성명 난수&quot;">​</a></h3><p>성명을 고르는 난수는 인물 스트림만 쓴다. 다른 스트림으로 성명을 고르지 않는다.</p><h3 id="rsave-10-저장-내용" tabindex="-1">RSAVE-10 저장 내용 <a class="header-anchor" href="#rsave-10-저장-내용" aria-label="Permalink to &quot;RSAVE-10 저장 내용&quot;">​</a></h3><p>저장 파일에는 판본이 붙은 세계 상태를 담는다. 명령·사건의 위치와 콘텐츠 판본이 빠지면 안 된다. 진행 중인 전투의 중간 지점도 저장 대상이다.</p><h3 id="rsave-11-원자-쓰기" tabindex="-1">RSAVE-11 원자 쓰기 <a class="header-anchor" href="#rsave-11-원자-쓰기" aria-label="Permalink to &quot;RSAVE-11 원자 쓰기&quot;">​</a></h3><p>쓰기는 임시 파일에서 시작한다. 검사값을 확인한 뒤에만 원본과 바꾼다.</p><h3 id="rsave-12-거부" tabindex="-1">RSAVE-12 거부 <a class="header-anchor" href="#rsave-12-거부" aria-label="Permalink to &quot;RSAVE-12 거부&quot;">​</a></h3><p>지원하지 않는 버전은 조용히 읽지 않는다. 잘린 파일도 잘못된 체크섬도 조용히 읽지 않는다.</p><h3 id="rsave-13-오류와-백업" tabindex="-1">RSAVE-13 오류와 백업 <a class="header-anchor" href="#rsave-13-오류와-백업" aria-label="Permalink to &quot;RSAVE-13 오류와 백업&quot;">​</a></h3><p>거부하면 명확한 오류를 반환한다. 이전 백업은 보존한다.</p><h3 id="rsave-14-전투-저장-시점" tabindex="-1">RSAVE-14 전투 저장 시점 <a class="header-anchor" href="#rsave-14-전투-저장-시점" aria-label="Permalink to &quot;RSAVE-14 전투 저장 시점&quot;">​</a></h3><p>전투 컨텍스트 발행 전이 저장 허용 지점이다. 전투 턴이 끝난 중간 지점에서도 저장한다. 결과 정산 완료 뒤에 다시 연다.</p><h3 id="rsave-15-중간-저장-읽기" tabindex="-1">RSAVE-15 중간 저장 읽기 <a class="header-anchor" href="#rsave-15-중간-저장-읽기" aria-label="Permalink to &quot;RSAVE-15 중간 저장 읽기&quot;">​</a></h3><p>중간 저장을 읽을 때 캠페인을 다시 조회하지 않는다. 저장된 불변 컨텍스트와 전투 명령 기록을 복원한다.</p><h3 id="rsave-16-공간-연속" tabindex="-1">RSAVE-16 공간 연속 <a class="header-anchor" href="#rsave-16-공간-연속" aria-label="Permalink to &quot;RSAVE-16 공간 연속&quot;">​</a></h3><p>저장 뒤에도 칸에 누가 서 있는지가 이어진다. 어느 쪽을 보며 어디까지 보이는지도 그대로다.</p><h2 id="판정-순서" tabindex="-1">판정 순서 <a class="header-anchor" href="#판정-순서" aria-label="Permalink to &quot;판정 순서&quot;">​</a></h2><ol><li>시작값과 선택 기록을 고정한다.</li><li>난수 스트림을 전투·조우·세계 사건으로 가른다.</li><li>성명 난수는 인물 스트림만 연다.</li><li>상태 변경마다 원인 ID와 명령, 세계 시간, 주체와 대상, 전후 해시, 규칙·콘텐츠 버전을 원장에 적는다.</li><li>면담·거래·후계 지지는 인물 미시 줄로만 남긴다.</li><li>미시 줄의 합이 임계를 넘으면 세계 사건으로 올린다.</li><li>저장 내용은 판본 세계 상태, 명령·사건 위치, 콘텐츠 판본, 전투 중간 지점으로 한정한다.</li><li>임시 파일에 쓰고 검사값을 확인한다.</li><li>확인된 뒤에만 원본과 바꾼다.</li><li>지원하지 않는 버전, 잘린 파일, 잘못된 체크섬은 거부하고 오류를 반환한다.</li><li>이전 백업을 보존한다.</li><li>전투 저장은 컨텍스트 발행 전, 턴 종료 중간 지점, 정산 완료 뒤에만 연다.</li><li>중간 저장 읽기는 저장된 불변 컨텍스트와 전투 명령 기록만 복원한다.</li><li>칸의 위치·방향·시야가 저장 전과 같은지 대조한다.</li></ol><h2 id="금지-사항" tabindex="-1">금지 사항 <a class="header-anchor" href="#금지-사항" aria-label="Permalink to &quot;금지 사항&quot;">​</a></h2><ul><li>같은 시작값과 선택 기록이 다른 세계 상태를 내는 일</li><li>같은 기록이 다른 사건 검사값을 내는 일</li><li>한 시스템 처리 순서가 다른 시스템 결과를 흔드는 일</li><li>난수 스트림을 섞어 쓰는 일</li><li>원장 없이 상태를 바꾸는 일</li><li>원장 항목을 빠진 채로 확정하는 일</li><li>인물 행위를 임계 전에 세계 사건으로 올리는 일</li><li>성명 난수에 인물 스트림 이외를 쓰는 일</li><li>검사값 확인 전에 원본을 바꾸는 일</li><li>지원하지 않는 버전을 조용히 읽는 일</li><li>잘린 파일을 조용히 읽는 일</li><li>잘못된 체크섬을 조용히 읽는 일</li><li>이전 백업을 버리는 일</li><li>중간 저장을 읽을 때 캠페인을 다시 조회하는 일</li><li>저장 뒤 칸의 위치·방향·시야를 다시 굴리는 일</li></ul><h2 id="출처" tabindex="-1">출처 <a class="header-anchor" href="#출처" aria-label="Permalink to &quot;출처&quot;">​</a></h2><ul><li>docs/game-logic/Save-and-Determinism.md</li><li>계약 수치는 구현 상수를 우선한다</li><li>원문에 잠긴 수치는 없다. 표는 원문 문구만 옮겼다</li><li>인물 미시 줄의 임계는 원문에 숫자로 적혀 있지 않다</li><li>후계·이름 로스터 문서는 원문이 가리키는 미시 줄 위치일 뿐이며 본 규칙에 수치를 보태지 않는다</li></ul>',45)])])}const m=e(i,[["render",d]]);export{b as __pageData,m as default};
